function majorityWithMap(nums) {
  const counts = new Map();
  for (const x of nums) {
    counts.set(x, (counts.get(x) ?? 0) + 1);
    if (counts.get(x) > nums.length / 2) return x;
  }
}

function majorityElement(nums) {
  let candidate = null;
  let count = 0;
  for (const x of nums) {
    if (count === 0) candidate = x;       // nobody is ahead: x takes the lead
    count += x === candidate ? 1 : -1;    // a vote for, or a vote cancelled
  }
  return candidate;
}

def majority_element(nums):
    candidate, count = None, 0
    for x in nums:
        if count == 0:
            candidate = x                 # nobody is ahead: x takes the lead
        count += 1 if x == candidate else -1
    return candidate

class Solution {
    public int majorityElement(int[] nums) {
        int candidate = 0, count = 0;
        for (int x : nums) {
            if (count == 0) candidate = x;    // nobody is ahead: x takes the lead
            count += (x == candidate) ? 1 : -1;
        }
        return candidate;
    }
}

